export function resumeAction(status: RunStatus): ResumeAction {
	switch (status) {
		case "blocked":
			return { kind: "answer" }
		case "crashed":
		case "cancelled":
			return { kind: "rerun" }
		case "completed":
			return { kind: "error", reason: "run is already completed; start a new run instead" }
		case "in_progress":
			return { kind: "error", reason: "run is currently in progress" }
	}
}

